<?php
defined( 'ABSPATH' ) || exit;
if ( ! current_user_can( 'manage_options' ) ) { echo '<div class="tutor-alert">Administrator access is required.</div>'; return; }
global $wpdb;
$base = STM_Tutor_Popup_Maker::dashboard_url();
$campaigns = STM_Tutor_Popup_Maker::get_campaigns();
$table = $wpdb->prefix . STM_Tutor_Popup_Maker::TABLE_NAME;
$lead_counts = array();
foreach ( $wpdb->get_results( "SELECT popup_id, COUNT(*) AS total FROM {$table} GROUP BY popup_id" ) as $row ) { $lead_counts[ (int) $row->popup_id ] = (int) $row->total; }
$active = count( array_filter( $campaigns, static function( $post ) { return 'publish' === $post->post_status; } ) );
$view = isset( $_GET['view'] ) && 'leads' === $_GET['view'] ? 'leads' : 'campaigns';
$editing = isset( $_GET['popup'] );
$popup_id = $editing ? absint( $_GET['popup'] ) : 0;
$popup = STM_Tutor_Popup_Maker::get_popup_data( $popup_id );
$filter = absint( $_GET['campaign'] ?? 0 );
$leads = 'leads' === $view ? $wpdb->get_results( $filter ? $wpdb->prepare( "SELECT * FROM {$table} WHERE popup_id=%d ORDER BY id DESC LIMIT 100", $filter ) : "SELECT * FROM {$table} ORDER BY id DESC LIMIT 100" ) : array();
$csv = wp_nonce_url( add_query_arg( array( 'action' => 'download_popup_leads_csv', 'campaign' => $filter ), admin_url( 'admin-post.php' ) ), 'download_popup_leads_csv' );
$notices = array( 'saved' => 'Your popup has been saved.', 'activate' => 'Popup activated.', 'pause' => 'Popup paused.', 'trash' => 'Popup moved to trash. Its leads and media have been kept.', 'duplicated' => 'Popup duplicated as a paused draft.' );
$notice_key = sanitize_key( wp_unslash( $_GET['notice'] ?? '' ) );
$input = static function( $name, $label, $value, $type = 'text', $extra = '' ) {
    ?><label class="pm-field" for="pm-<?php echo esc_attr( $name ); ?>"><span><?php echo esc_html( $label ); ?></span><input id="pm-<?php echo esc_attr( $name ); ?>" name="<?php echo esc_attr( $name ); ?>" type="<?php echo esc_attr( $type ); ?>" value="<?php echo esc_attr( $value ); ?>" <?php echo $extra; // Only fixed attributes supplied below. ?>></label><?php
};
?>
<div class="pm-workspace">
 <header class="pm-page-head"><div><a class="pm-kicker" href="<?php echo esc_url( $base ); ?>">MYTENNISCLOUD / GROWTH</a><h1><?php echo $editing ? ( $popup['id'] ? 'Edit popup' : 'Create a popup' ) : 'Popup & Leads'; ?></h1><p><?php echo $editing ? 'A thoughtful offer. A clear next step for your visitors.' : 'Create meaningful offers and turn interest into a conversation.'; ?></p></div><div class="pm-head-actions"><?php if ( $editing ) : ?><a class="pm-button pm-secondary" href="<?php echo esc_url( $base ); ?>">← All popups</a><?php else : ?><a class="pm-button" href="<?php echo esc_url( add_query_arg( 'popup', 'new', $base ) ); ?>"><span>＋</span> Create popup</a><?php endif; ?></div></header>
 <div class="pm-stats"><?php foreach ( array( 'Total popups' => count( $campaigns ), 'Active now' => $active, 'Paused / draft' => count( $campaigns ) - $active, 'Captured leads' => array_sum( $lead_counts ) ) as $label => $number ) : ?><div class="pm-stat"><span><?php echo esc_html( $label ); ?></span><strong><?php echo esc_html( number_format_i18n( $number ) ); ?></strong><?php if ( 'Active now' === $label ) : ?><i class="pm-stat-dot"></i><?php endif; ?></div><?php endforeach; ?></div>
 <?php if ( isset( $notices[ $notice_key ] ) ) : ?><div class="pm-notice" role="status"><?php echo esc_html( $notices[ $notice_key ] ); ?></div><?php endif; ?>
 <div id="pm-alert" class="pm-notice pm-error" role="alert" hidden></div>
 <?php if ( ! $editing ) : ?>
 <nav class="pm-tabs" aria-label="Popup management"><a href="<?php echo esc_url( $base ); ?>" <?php echo 'campaigns' === $view ? 'aria-current="page"' : ''; ?>>All popups <span><?php echo count( $campaigns ); ?></span></a><a href="<?php echo esc_url( add_query_arg( 'view', 'leads', $base ) ); ?>" <?php echo 'leads' === $view ? 'aria-current="page"' : ''; ?>>Captured leads <span><?php echo esc_html( array_sum( $lead_counts ) ); ?></span></a></nav>
 <?php if ( 'campaigns' === $view ) : ?>
 <div class="pm-list-heading"><div><h2>Your offers, at a glance</h2><p>Every active popup is eligible to appear. Visitors see one at a time, in priority order.</p></div><label class="pm-status-filter">Show <select id="pm-status-filter"><option value="all">All statuses</option><option value="publish">Active</option><option value="paused">Paused / draft</option></select></label></div>
 <div class="pm-campaign-list">
 <?php if ( ! $campaigns ) : ?><div class="pm-empty"><span class="pm-empty-icon">↗</span><h2>Your next conversation starts here.</h2><p>Create an offer, add a useful resource, and welcome new leads.</p><a class="pm-button" href="<?php echo esc_url( add_query_arg( 'popup', 'new', $base ) ); ?>">Create your first popup</a></div><?php endif; ?>
 <?php foreach ( $campaigns as $post ) : $item = STM_Tutor_Popup_Maker::get_popup_data( $post->ID ); $live = 'publish' === $item['status']; ?>
 <article class="pm-campaign" data-campaign="<?php echo $post->ID; ?>" data-status="<?php echo esc_attr( $live ? 'publish' : 'paused' ); ?>">
  <div class="pm-campaign-main"><div class="pm-thumb"><?php if ( $item['banner_url'] ) : ?><img src="<?php echo esc_url( $item['banner_url'] ); ?>" alt="" loading="lazy"><?php else : ?><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 14V7l13-4v15L4 14Zm0 0 2 6h4l-2-5m9-8h3v7h-3"/></svg><?php endif; ?></div><div class="pm-campaign-copy"><div class="pm-campaign-title"><h3><?php echo esc_html( $item['title'] ); ?></h3><span class="pm-badge <?php echo $live ? 'pm-live' : ''; ?>"><?php echo $live ? 'Active' : 'Paused / draft'; ?></span></div><p><?php echo esc_html( wp_trim_words( $item['subtitle'], 20 ) ?: 'No description added yet.' ); ?></p><div class="pm-meta"><span>#<?php echo $post->ID; ?></span><span><?php echo $item['gift_id'] ? 'Document gift attached' : 'Lead capture'; ?></span><span><?php echo esc_html( $item['delay_sec'] ); ?>s delay</span><span>Priority <?php echo esc_html( $item['priority'] ); ?></span></div></div><a class="pm-lead-count" href="<?php echo esc_url( add_query_arg( array( 'view' => 'leads', 'campaign' => $post->ID ), $base ) ); ?>"><strong><?php echo esc_html( $lead_counts[ $post->ID ] ?? 0 ); ?></strong><span>leads</span></a></div>
  <footer class="pm-campaign-actions"><div><a class="pm-button pm-secondary pm-small" href="<?php echo esc_url( add_query_arg( 'popup', $post->ID, $base ) ); ?>">Edit offer</a><button type="button" class="pm-text-button" data-preview="<?php echo esc_url( STM_Tutor_Popup_Maker::preview_url( $post->ID ) ); ?>">Preview ↗</button></div><div><button type="button" class="pm-text-button" data-operation="<?php echo $live ? 'pause' : 'activate'; ?>" data-id="<?php echo $post->ID; ?>"><?php echo $live ? 'Pause' : 'Activate'; ?></button><button type="button" class="pm-text-button" data-operation="duplicate" data-id="<?php echo $post->ID; ?>">Duplicate</button><button type="button" class="pm-text-button pm-danger" data-operation="trash" data-id="<?php echo $post->ID; ?>">Trash</button></div></footer>
 </article>
 <?php endforeach; ?>
 </div><p id="pm-filter-empty" class="pm-empty" hidden>No popups match this status.</p>
 <?php else : ?>
 <div class="pm-leads-heading"><div><h2>People behind the numbers</h2><p>Showing the latest 100 submissions. Export includes every matching lead.</p></div><a class="pm-button pm-secondary" href="<?php echo esc_url( $csv ); ?>">Export CSV ↓</a></div>
 <form class="pm-lead-filter" method="get"><input type="hidden" name="view" value="leads"><label for="pm-campaign-filter">Popup</label><select name="campaign" id="pm-campaign-filter"><option value="0">All popups</option><?php foreach ( $campaigns as $post ) : ?><option value="<?php echo $post->ID; ?>" <?php selected( $filter, $post->ID ); ?>><?php echo esc_html( $post->post_title ); ?></option><?php endforeach; ?></select><button class="pm-button pm-secondary pm-small" type="submit">Apply filter</button></form>
 <div class="pm-table-wrap"><table class="pm-table"><thead><tr><th>Name & email</th><th>Popup</th><th>Phone</th><th>Message</th><th>Submitted</th></tr></thead><tbody><?php if ( ! $leads ) : ?><tr><td colspan="5" class="pm-empty">No leads yet. New submissions will appear here.</td></tr><?php endif; ?><?php foreach ( $leads as $lead ) : ?><tr><td><strong><?php echo esc_html( $lead->name ?: 'Visitor' ); ?></strong><a href="mailto:<?php echo esc_attr( $lead->email ); ?>"><?php echo esc_html( $lead->email ); ?></a></td><td><?php echo esc_html( get_the_title( $lead->popup_id ) ?: 'Deleted popup' ); ?></td><td><?php echo esc_html( $lead->phone ?: '—' ); ?></td><td><?php echo esc_html( $lead->message ?: '—' ); ?></td><td><?php echo esc_html( mysql2date( 'M j, Y · g:i a', $lead->created_at ) ); ?></td></tr><?php endforeach; ?></tbody></table></div>
 <?php endif; ?>
 <?php else : ?>
 <?php if ( $popup_id && ! $popup['id'] ) : ?><p class="pm-notice pm-error">This popup no longer exists. Save this form to create a new one.</p><?php endif; ?>
 <form id="pm-editor" class="pm-editor" method="post"><input type="hidden" name="popup_id" value="<?php echo esc_attr( $popup['id'] ); ?>"><div class="pm-editor-main">
 <section class="pm-panel"><header><span class="pm-step">01</span><div><h2>The offer</h2><p>Lead with something your visitors will value.</p></div></header><div class="pm-panel-body">
 <?php $input( 'title', 'Popup headline', $popup['title'], 'text', 'required maxlength="180" placeholder="Your free guide to a smarter tennis game"' ); ?>
 <label class="pm-field" for="pm-subtitle"><span>Description</span><textarea id="pm-subtitle" name="subtitle" rows="3" placeholder="Tell visitors what they will receive and why it matters."><?php echo esc_textarea( $popup['subtitle'] ); ?></textarea></label>
 <?php $input( 'cta_text', 'Submit button text', $popup['cta_text'], 'text', 'maxlength="100"' ); ?>
 <div class="pm-asset" data-asset="image"><div class="pm-asset-heading"><div><h3>Banner image</h3><p>Choose a photo that brings your offer to life.</p></div><span class="pm-optional">Optional</span></div><input type="hidden" name="banner_id" value="<?php echo esc_attr( $popup['banner_id'] ); ?>"><input type="hidden" name="banner_url" value="<?php echo esc_url( $popup['banner_url'] ); ?>"><div class="pm-image-preview" <?php echo $popup['banner_url'] ? '' : 'hidden'; ?>><img <?php if ( $popup['banner_url'] ) { echo 'src="' . esc_url( $popup['banner_url'] ) . '"'; } ?> alt="Selected popup banner"></div><div class="pm-asset-buttons"><button type="button" class="pm-button pm-secondary pm-small" data-media-library>Media Library</button><button type="button" class="pm-text-button" data-device-upload>Upload from device</button><button type="button" class="pm-text-button pm-danger" data-remove-asset <?php echo $popup['banner_url'] ? '' : 'hidden'; ?>>Remove</button></div><input type="file" data-asset-file accept="image/jpeg,image/png,image/webp,image/gif" hidden><p class="pm-upload-status" role="status" aria-live="polite">JPG, PNG, WebP or GIF. Saved to your WordPress Media Library.</p></div>
 </div></section>
 <section class="pm-panel"><header><span class="pm-step">02</span><div><h2>The free gift</h2><p>Give visitors something useful, instantly.</p></div></header><div class="pm-panel-body">
 <div class="pm-asset" data-asset="document"><input type="hidden" name="gift_id" value="<?php echo esc_attr( $popup['gift_id'] ); ?>"><div class="pm-document-preview" <?php echo $popup['gift_id'] ? '' : 'hidden'; ?>><span class="pm-document-icon">↓</span><div><strong data-document-name><?php echo esc_html( basename( (string) get_attached_file( $popup['gift_id'] ) ) ); ?></strong><span>Delivered after successful form submission</span></div><button type="button" class="pm-text-button pm-danger" data-remove-asset>Remove</button></div><div class="pm-asset-buttons"><button type="button" class="pm-button pm-secondary pm-small" data-media-library>Choose document</button><button type="button" class="pm-text-button" data-device-upload>Upload document</button></div><input type="file" data-asset-file accept=".pdf,.doc,.docx,.odt,.txt" hidden><p class="pm-upload-status" role="status" aria-live="polite">PDF, DOC, DOCX, ODT or TXT. Choose an existing file or upload a new one.</p></div>
 <div class="pm-tip"><span>↳</span><p>Visitors submit the form, then receive a download button on the confirmation screen. Each link lasts 24 hours.</p></div>
 <?php $input( 'gift_label', 'Download button text', $popup['gift_label'], 'text', 'maxlength="100"' ); ?>
 <label class="pm-field" for="pm-success-message"><span>Confirmation message</span><textarea id="pm-success-message" name="success_message" rows="2"><?php echo esc_textarea( $popup['success_message'] ); ?></textarea></label>
 </div></section>
 <section class="pm-panel"><header><span class="pm-step">03</span><div><h2>Form & display</h2><p>A few details. The right moment.</p></div></header><div class="pm-panel-body"><div class="pm-field"><span>Details to collect</span><div class="pm-field-options"><label><input type="checkbox" checked disabled> Email <small>Required</small></label><?php foreach ( array( 'field_name' => 'Name', 'field_phone' => 'Phone number', 'field_message' => 'Message' ) as $name => $label ) : ?><label><input type="checkbox" name="<?php echo esc_attr( $name ); ?>" value="1" <?php checked( $popup[ $name ], 1 ); ?>> <?php echo esc_html( $label ); ?></label><?php endforeach; ?></div></div><div class="pm-input-grid"><?php $input( 'delay_sec', 'Delay before showing (seconds)', $popup['delay_sec'], 'number', 'min="0" max="120" required' ); $input( 'frequency_days', 'Hide after dismissal (days)', $popup['frequency_days'], 'number', 'min="0" max="365" required' ); $input( 'priority', 'Display priority', $popup['priority'], 'number', 'min="0" max="100" required' ); ?></div><p class="pm-help">Higher priorities appear first. Active popups display one at a time. A frequency of 0 allows the offer on each page visit.</p></div></section>
 <div class="pm-save-bar"><span id="pm-save-status" role="status">Changes are saved when you click Save popup.</span><button class="pm-button" type="submit" id="pm-save">Save popup <span>↗</span></button></div>
 </div><aside class="pm-editor-aside"><section class="pm-panel pm-publish"><span class="pm-kicker">PUBLISHING</span><h2>Ready when you are.</h2><label class="pm-radio"><input type="radio" name="enabled" value="0" <?php checked( $popup['status'] !== 'publish' ); ?>><span><strong>Paused / draft</strong><small>Keep this offer off your website.</small></span></label><label class="pm-radio"><input type="radio" name="enabled" value="1" <?php checked( $popup['status'], 'publish' ); ?>><span><strong>Active</strong><small>Show to visitors after saving.</small></span></label><p class="pm-help">Every popup has its own status, timing and frequency.</p></section><section class="pm-panel pm-preview-card"><div class="pm-preview-art"><span>YOUR NEXT STEP</span><i></i><i></i><b>↗</b></div><h3>See it through their eyes.</h3><p>Preview the actual popup without changing its status or recording a lead.</p><?php if ( $popup['id'] ) : ?><button type="button" class="pm-button pm-secondary" data-preview="<?php echo esc_url( STM_Tutor_Popup_Maker::preview_url( $popup['id'] ) ); ?>">Preview saved popup ↗</button><?php else : ?><span class="pm-help">Save your popup to unlock its preview.</span><?php endif; ?></section></aside></form>
 <?php endif; ?>
